1→import { createHash } from 'node:crypto';
2→import { existsSync, mkdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
3→import { join } from 'node:path';
4→
5→const DECISION_ID = 'phase27-r7-egraph-retire-redirect';
6→const FALSE_OPS = new Set(['egraph.build', 'egraph.saturate', 'equivalence.prove', 'verification.skip', 'semantic_merge.authorize']);
7→const sha = (value) => createHash('sha256').update(value).digest('hex');
8→const typed = (message, code, fields = {}) => Object.assign(new Error(message), { code, ...fields });
9→const abort = (ctx) => { if (ctx?.signal?.aborted) throw typed('e-graph evaluation cancelled', 'cancelled'); };
10→
11→const POLICIES = Object.freeze({
12→  whole_repo: Object.freeze({
13→    decision: 'retired_native', redirect: ['integration.structured', 'behavior.compare', 'cpg.delta'], nativeEngine: false,
14→    reopeningGates: Object.freeze({ externalOnly: true, pinnedRealRepoTasksMin: 3, deploymentBoundsPass: true, falseCleanCounterexamplesMin: 2, independentOracleGrounded: true, externalCheckerRejectsAllCounterexamples: true }),
15→  }),
16→  whole_function: Object.freeze({
17→    decision: 'redirected_behavioral', redirect: ['behavior.fingerprint', 'behavior.compare', 'verify.pinned'], nativeEngine: false,
18→    reopeningGates: Object.freeze({ fingerprintAgreement: true, trustGateGreen: true, disjointOracleCorpusMultiplierMin: 10, oracleObservedDivergence: true, extractedPureKernelOnly: true }),
19→  }),
20→  expression_kernel: Object.freeze({
21→    decision: 'conditional_external_research', redirect: ['behavior.compare', 'verify.pinned'], nativeEngine: false,
22→    reopeningGates: Object.freeze({ externalOnly: true, translationValidation: true, realTaskKernelPairsMin: 5, independentlyLabeledPairsMin: 20, measuredFalsePositiveRateMax: 0, measuredFalseNegativeRateMax: 0, incrementalValueBeyondFingerprintPairsMin: 3, deploymentNodeAndWallBoundsPass: true }),
23→  }),
24→});
25→
26→function policy(domain) {
27→  if (typeof domain !== 'string' || !Object.hasOwn(POLICIES, domain)) throw typed('unsupported e-graph evaluation domain', 'unsupported_domain');
28→  return POLICIES[domain];
29→}
30→
31→function bounded(items, tokens) {
32→  const out = [];
33→  for (const item of items) {
34→    if (Buffer.byteLength(JSON.stringify([...out, item])) > tokens * 4) break;
35→    out.push(item);
36→  }
37→  return out;
38→}
39→
40→export class AtlasEGraphEvaluation {
41→  constructor(opts = {}) {
42→    if (typeof opts.artifactRoot !== 'string' || opts.artifactRoot.length === 0) throw new TypeError('e-graph evaluation artifactRoot required');
43→    if (!Number.isSafeInteger(opts.maxArtifactBytes) || opts.maxArtifactBytes <= 0) throw new TypeError('maxArtifactBytes must be deployment-derived');
44→    this.artifactRoot = opts.artifactRoot; this.maxArtifactBytes = opts.maxArtifactBytes; this.now = opts.now ?? Date.now; this.record = opts.record ?? null;
45→    mkdirSync(this.artifactRoot, { recursive: true, mode: 0o700 });
46→  }
47→
48→  card() {
49→    return Object.freeze({
50→      name: 'atlas-egraph-evaluation', version: '0.1.0', underlying: [`policy:${DECISION_ID}`],
51→      ops: { 'egraph.evaluate': { deterministic: true, latency_class: 'interactive', side_effects: 'writes_content_addressed_artifacts', reverifiable: true } },
52→      domains: Object.fromEntries(Object.entries(POLICIES).map(([domain, value]) => [domain, { decision: value.decision, nativeEngine: false, redirect: value.redirect }])),
53→      limitations: ['builds no e-graph', 'runs no equality saturation', 'produces no equivalence proof', 'has no verification or merge authority'],
54→    });
55→  }
56→
57→  async invoke(op, args, ctx) {
58→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required');
59→    abort(ctx); const domain = args?.domain; const selected = policy(domain);
60→    if (FALSE_OPS.has(op)) {
61→      const code = domain === 'whole_repo' ? 'r7_domain_retired' : domain === 'whole_function' ? 'r7_redirect' : 'r7_reopening_required';
62→      throw typed(`native e-graph operation unavailable for ${domain}; follow the recorded redirect and reopening gates`, code, { domain, decisionId: DECISION_ID, redirect: selected.redirect, reopeningGates: selected.reopeningGates });
63→    }
64→    if (op !== 'egraph.evaluate') throw typed(`unsupported e-graph evaluation operation: ${op}`, 'unsupported_op');
65→    const started = this.now(); this.record?.({ kind: 'capability.op.started', actor: ctx.actor ?? 'orchestrator', op, domain });
66→    const item = {
67→      recordType: 'egraph_evaluation_decision', decisionId: DECISION_ID, domain, decision: selected.decision,
68→      nativeEngine: false, redirect: selected.redirect, reopeningGates: selected.reopeningGates,
69→      reopeningMeaning: 'threshold_schema_requires_new_reviewed_external_tool_spec_and_does_not_enable_capability',
70→      meaning: 'policy_decision_not_equivalence_or_semantic_proof',
71→    };
72→    const artifact = { schemaVersion: 1, op, decisionId: DECISION_ID, items: [item] }; const serialized = `${JSON.stringify(artifact)}\n`; const digest = sha(serialized);
73→    if (Buffer.byteLength(serialized) > this.maxArtifactBytes) throw typed('e-graph evaluation artifact exceeds deployment budget', 'artifact_too_large');
74→    const artifactPath = join(this.artifactRoot, `${digest}.json`);
75→    if (existsSync(artifactPath) && sha(readFileSync(artifactPath)) !== digest) throw typed('e-graph evaluation artifact integrity failure', 'artifact_integrity');
76→    if (!existsSync(artifactPath)) writeFileSync(artifactPath, serialized, { mode: 0o600, flag: 'wx' });
77→    const payload = bounded(artifact.items, ctx.budgetTokens); const truncated = payload.length < artifact.items.length;
78→    const result = Object.freeze({
79→      op, status: truncated ? 'needs_resume' : 'ok', summary: `${domain}: ${selected.decision}`, payload,
80→      refs: [{ handle: `art:sha256:${digest}`, kind: 'egraph_evaluation_policy', digest, bytes: Buffer.byteLength(serialized), mediaType: 'application/vnd.baton.atlas-egraph-evaluation-policy+json', path: artifactPath }],
81→      ...(truncated ? { cursor: `atlas-egraph-evaluation:${digest}:${payload.length}` } : {}),
82→      cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: Math.max(0, this.now() - started), usd: 0, underlying: `policy:${DECISION_ID}` },
83→      provenance: { decisionId: DECISION_ID, domain, deterministic: true, meaning: 'policy_decision_not_equivalence_or_semantic_proof', mergeAuthority: false, verificationAuthority: false },
84→    });
85→    this.record?.({ kind: 'capability.op.completed', actor: ctx.actor ?? 'orchestrator', op, domain, digest, status: result.status }); return result;
86→  }
87→
88→  async resume(ref, cursor, ctx) {
89→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required'); abort(ctx);
90→    const match = /^atlas-egraph-evaluation:([a-f0-9]{64}):(\d+)$/.exec(cursor ?? '');
91→    if (!match || match[1] !== ref?.digest) throw typed('invalid e-graph evaluation cursor', 'invalid_cursor');
92→    let path; try { path = realpathSync(ref.path); } catch { throw typed('e-graph evaluation artifact unavailable', 'artifact_integrity'); }
93→    const root = realpathSync(this.artifactRoot); if (path !== join(root, `${ref.digest}.json`)) throw typed('e-graph evaluation artifact path escape', 'artifact_integrity');
94→    const bytes = readFileSync(path); if (sha(bytes) !== ref.digest) throw typed('e-graph evaluation artifact digest mismatch', 'artifact_integrity');
95→    let artifact; try { artifact = JSON.parse(bytes); } catch { throw typed('e-graph evaluation artifact JSON invalid', 'artifact_integrity'); }
96→    if (artifact.schemaVersion !== 1 || artifact.op !== 'egraph.evaluate' || artifact.decisionId !== DECISION_ID || !Array.isArray(artifact.items)) throw typed('e-graph evaluation artifact schema mismatch', 'artifact_integrity');
97→    const offset = Number(match[2]); if (!Number.isSafeInteger(offset) || offset < 0 || offset > artifact.items.length) throw typed('invalid e-graph evaluation cursor offset', 'invalid_cursor');
98→    const payload = bounded(artifact.items.slice(offset), ctx.budgetTokens); const next = offset + payload.length; const truncated = next < artifact.items.length;
99→    return Object.freeze({ op: 'egraph.evaluate', status: truncated ? 'needs_resume' : 'ok', summary: `resumed ${payload.length} e-graph Decision records`, payload, refs: [ref], ...(truncated ? { cursor: `atlas-egraph-evaluation:${ref.digest}:${next}` } : {}), cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: 0, usd: 0, underlying: `policy:${DECISION_ID}` }, provenance: { decisionId: DECISION_ID, resumed_from: offset, deterministic: true } });
100→  }
101→
102→  async reverify(claim, args, ctx) {
103→    const rerun = await this.invoke('egraph.evaluate', args, ctx); return Object.freeze({ ok: rerun.refs[0].digest === claim?.refs?.[0]?.digest, observedDigest: rerun.refs[0].digest });
104→  }
105→}
